```sql
-- MASTER SCHEMA SYNC SCRIPT (V16)
-- Run this in Supabase SQL Editor to fix missing types, enum errors, and recursion.

BEGIN;

-- 1. CRITICAL FIXES: Notification Type & Obsolete Constraints

-- Safely convert notifications.type to text if it isn't already
DO $$ 
BEGIN
    -- Check if 'type' column exists and is NOT text (e.g. it is the broken enum)
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
        AND table_name = 'notifications' 
        AND column_name = 'type' 
        AND data_type != 'text'
    ) THEN
        -- Add temp column
        ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS type_new text;

        -- Try to copy data safely. If enum is missing, simple cast might fail, so we handle it.
        BEGIN
            UPDATE public.notifications SET type_new = CAST(type AS text);
        EXCEPTION WHEN OTHERS THEN
            -- If cast fails (e.g. enum completely missing from pg_type), default to system notification
            UPDATE public.notifications SET type_new = 'system_notification';
        END;

        -- Drop the old column and rename the new one
        ALTER TABLE public.notifications DROP COLUMN type CASCADE;
        ALTER TABLE public.notifications RENAME COLUMN type_new TO type;
    END IF;

    -- Ensure type column exists if it was somehow missing entirely
    IF NOT EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
        AND table_name = 'notifications' 
        AND column_name = 'type'
    ) THEN
        ALTER TABLE public.notifications ADD COLUMN type text DEFAULT 'system_notification';
    END IF;
END $$;

-- Drop the obsolete enum type if it still exists
DROP TYPE IF EXISTS notification_type CASCADE;

-- Drop obsolete subject code constraints
