CREATE OR REPLACE FUNCTION enroll_in_subject(subject_code_to_enroll text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_subject_id bigint;
  v_teacher_id uuid;
BEGIN
  SELECT id, teacher_id INTO v_subject_id, v_teacher_id FROM subjects WHERE subject_code = subject_code_to_enroll;
  IF v_subject_id IS NULL THEN RETURN json_build_object('success', false, 'message', 'Invalid code.'); END IF;

  -- Insert Enrollment
  INSERT INTO subject_enrollments (subject_id, student_id, status) VALUES (v_subject_id, auth.uid(), 'pending') ON CONFLICT DO NOTHING;

  -- Failsafe Notification: If this block fails (e.g. recursion/RLS), catch it and continue so enrollment persists
  BEGIN
    INSERT INTO notifications (recipient_id, actor_id, type, related_entity_id, related_subject_id)
    VALUES (v_teacher_id, auth.uid(), 'enrollment_request'::text, (SELECT id FROM subject_enrollments WHERE subject_id = v_subject_id AND student_id = auth.uid()), v_subject_id);
  EXCEPTION WHEN OTHERS THEN
    -- Log warning but allow success
    RAISE WARNING 'Notification failed: %', SQLERRM;
  END;

  RETURN json_build_object('success', true, 'message', 'Request sent.');
END;
$$;

CREATE OR REPLACE FUNCTION approve_enrollment_request(enrollment_id bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_student_id uuid;
  v_subject_id bigint;
BEGIN
  UPDATE subject_enrollments SET status = 'approved' WHERE id = enrollment_id RETURNING student_id, subject_id INTO v_student_id, v_subject_id;
  IF v_student_id IS NOT NULL THEN
    BEGIN
      INSERT INTO notifications (recipient_id, actor_id, type, related_entity_id, related_subject_id)
      VALUES (v_student_id, auth.uid(), 'enrollment_approved'::text, enrollment_id, v_subject_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Approval Notification failed: %', SQLERRM;
    END;
  END IF;
END;
$$;

