CREATE OR REPLACE FUNCTION admin_search_subjects(search_term text) RETURNS TABLE (id bigint, title text, subject_code text, teacher_name text, student_count bigint, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT s.id, s.title, s.subject_code, p.full_name, (SELECT COUNT(*) FROM subject_enrollments se WHERE se.subject_id = s.id AND se.status = 'approved'), s.created_at FROM subjects s JOIN profiles p ON s.teacher_id = p.id WHERE (search_term IS NULL OR s.title ILIKE '%'||search_term||'%' OR s.subject_code ILIKE '%'||search_term||'%' OR p.full_name ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_stats() RETURNS TABLE (total_users bigint, student_users bigint, teacher_users bigint, total_subjects bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY SELECT (SELECT COUNT(*) FROM profiles), (SELECT COUNT(*) FROM profiles WHERE role = 'Student'), (SELECT COUNT(*) FROM profiles WHERE role = 'Teacher'), (SELECT COUNT(*) FROM subjects);
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_activity_trends() RETURNS TABLE (activity_date text, new_users bigint, study_sessions bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY WITH dates AS (SELECT generate_series(CURRENT_DATE - INTERVAL '6 days', CURRENT_DATE, '1 day'::interval)::date AS day)
  SELECT to_char(d.day, 'Mon DD'), (SELECT COUNT(*) FROM profiles p WHERE p.created_at::date = d.day), (SELECT COUNT(*) FROM study_sessions s WHERE s.completed_at::date = d.day) FROM dates d ORDER BY d.day ASC;
END;
$$;

CREATE OR REPLACE FUNCTION get_friends_and_requests() RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_friends json;
  v_requests json;
BEGIN
  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_friends
  FROM friendships f JOIN profiles p ON (CASE WHEN f.user1_id = v_user_id THEN f.user2_id ELSE f.user1_id END) = p.id
  WHERE (f.user1_id = v_user_id OR f.user2_id = v_user_id) AND f.status = 'accepted';

  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_requests
  FROM friendships f JOIN profiles p ON f.requester_id = p.id
  WHERE f.user2_id = v_user_id AND f.status = 'pending';

  RETURN json_build_object('friends', COALESCE(v_friends, '[]'::json), 'requests', COALESCE(v_requests, '[]'::json));
END;
$$;

CREATE OR REPLACE FUNCTION search_students(search_term text) RETURNS TABLE (id uuid, full_name text, avatar_url text, course text) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.avatar_url, p.course FROM profiles p WHERE p.role = 'Student' AND p.id != auth.uid() AND p.full_name ILIKE '%'||search_term||'%' LIMIT 20;
END;
$$;

CREATE OR REPLACE FUNCTION invite_to_lobby(p_lobby_id bigint, p_invitee_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    INSERT INTO notifications (recipient_id, actor_id, type, related_entity_id) VALUES (p_invitee_id, auth.uid(), 'lobby_invite'::text, p_lobby_id);
END;
$$;

CREATE OR REPLACE FUNCTION mark_notifications_as_read(notification_ids bigint[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    UPDATE notifications SET is_read = true WHERE id = ANY(notification_ids) AND recipient_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION clear_read_notifications() RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM notifications WHERE recipient_id = auth.uid() AND is_read = true;
END;
$$;

COMMIT;

