/**
 * A definitive, robust function to get a readable string message from any error.
 * This function is designed to be "bulletproof" by defensively checking for
 * various error formats and translating common technical errors into user-friendly messages.
 *
 * @param error The error to process.
 * @returns A string representation of the error message.
 */

/* SQL Script to fix infinite recursion in RLS policies, enrollment permissions, analytics, and admin functions */
export const FIX_RECURSION_SQL = `
-- MASTER SCHEMA SYNC SCRIPT (V20 - CASE INSENSITIVE ENROLLMENT)
-- Run this in Supabase SQL Editor to fix "Invalid Code" errors during enrollment.

BEGIN;

-- 1. CRITICAL FIXES: Notification Type & Obsolete Constraints

-- Safely convert notifications.type to text if it isn't already
DO $$ 
BEGIN
    -- Check if 'type' column exists and is NOT text (e.g. it is the broken enum)
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
        AND table_name = 'notifications' 
        AND column_name = 'type' 
        AND data_type != 'text'
    ) THEN
        -- Add temp column
        ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS type_new text;

        -- Try to copy data safely.
        BEGIN
            UPDATE public.notifications SET type_new = CAST(type AS text);
        EXCEPTION WHEN OTHERS THEN
            UPDATE public.notifications SET type_new = 'system_notification';
        END;

        -- Drop the old column and rename the new one
        ALTER TABLE public.notifications DROP COLUMN type CASCADE;
        ALTER TABLE public.notifications RENAME COLUMN type_new TO type;
    END IF;

    -- Ensure type column exists
    IF NOT EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
        AND table_name = 'notifications' 
        AND column_name = 'type'
    ) THEN
        ALTER TABLE public.notifications ADD COLUMN type text DEFAULT 'system_notification';
    END IF;
END $$;

-- Drop the obsolete enum type if it still exists
DROP TYPE IF EXISTS notification_type CASCADE;

-- Drop obsolete subject code constraints
ALTER TABLE IF EXISTS public.subjects DROP CONSTRAINT IF EXISTS fk_subject_code_exists;
DROP TABLE IF EXISTS public.subject_codes CASCADE;

-- 2. TABLE DEFINITIONS (Idempotent)
CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email text,
  full_name text,
  role text DEFAULT 'Student',
  avatar_url text,
  course text,
  preferred_theme text DEFAULT 'system',
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.subjects (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title text NOT NULL,
    description text,
    image_url text,
    teacher_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    subject_code text DEFAULT substring(md5(random()::text) from 1 for 6),
    created_at timestamptz DEFAULT now()
);
-- Ensure unique subject_code
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'subjects_subject_code_key') THEN
        ALTER TABLE public.subjects ADD CONSTRAINT subjects_subject_code_key UNIQUE (subject_code);
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.decks (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
