CREATE TABLE IF NOT EXISTS public.subject_decks (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    subject_id bigint REFERENCES public.subjects(id) ON DELETE CASCADE NOT NULL,
    deck_id bigint REFERENCES public.decks(id) ON DELETE CASCADE NOT NULL,
    added_at timestamptz DEFAULT now(),
    UNIQUE(subject_id, deck_id)
