CREATE TABLE IF NOT EXISTS public.study_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    deck_id bigint REFERENCES public.decks(id) ON DELETE CASCADE NOT NULL,
    subject_id bigint REFERENCES public.subjects(id) ON DELETE SET NULL,
    score_percentage integer,
    correct_count integer,
    total_cards integer,
    completed_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recipient_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    type text NOT NULL,
    related_entity_id bigint,
    related_subject_id bigint REFERENCES public.subjects(id) ON DELETE CASCADE,
    is_read boolean DEFAULT false,
    created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.friendships (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user1_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    user2_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    requester_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    status text DEFAULT 'pending',
    created_at timestamptz DEFAULT now(),
    UNIQUE(user1_id, user2_id)
);

CREATE TABLE IF NOT EXISTS public.coop_lobbies (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    host_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    deck_id bigint REFERENCES public.decks(id) ON DELETE SET NULL,
    lobby_code text UNIQUE NOT NULL,
    status text DEFAULT 'waiting',
    created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.coop_lobby_members (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lobby_id bigint REFERENCES public.coop_lobbies(id) ON DELETE CASCADE NOT NULL,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL,
    score integer DEFAULT 0,
    joined_at timestamptz DEFAULT now(),
    UNIQUE(lobby_id, user_id)
);

-- 3. RESET RLS POLICIES (Prevent Recursion)
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE decks ENABLE ROW LEVEL SECURITY;
ALTER TABLE cards ENABLE ROW LEVEL SECURITY;
ALTER TABLE subject_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE subject_decks ENABLE ROW LEVEL SECURITY;
ALTER TABLE study_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE friendships ENABLE ROW LEVEL SECURITY;
ALTER TABLE coop_lobbies ENABLE ROW LEVEL SECURITY;
ALTER TABLE coop_lobby_members ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Profiles" ON profiles;
DROP POLICY IF EXISTS "Self Update Profile" ON profiles;
DROP POLICY IF EXISTS "Self Insert Profile" ON profiles;
DROP POLICY IF EXISTS "Public Read Subjects" ON subjects;
DROP POLICY IF EXISTS "Teacher Manage Subjects" ON subjects;
DROP POLICY IF EXISTS "Owner Manage Decks" ON decks;
DROP POLICY IF EXISTS "Public Read Decks" ON decks;
DROP POLICY IF EXISTS "Public Read Cards" ON cards;
DROP POLICY IF EXISTS "Owner Manage Cards" ON cards;
DROP POLICY IF EXISTS "Student Enroll" ON subject_enrollments;
DROP POLICY IF EXISTS "View Enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "Teacher Manage Enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "Delete Enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "Read Subject Decks" ON subject_decks;
DROP POLICY IF EXISTS "Manage Subject Decks" ON subject_decks;
DROP POLICY IF EXISTS "Users Manage Sessions" ON study_sessions;
DROP POLICY IF EXISTS "Teachers View Subject Sessions" ON study_sessions;
DROP POLICY IF EXISTS "Users Manage Own Notifications" ON notifications;
DROP POLICY IF EXISTS "System Insert Notifications" ON notifications;
DROP POLICY IF EXISTS "Friendship Access" ON friendships;
DROP POLICY IF EXISTS "Lobby Access" ON coop_lobbies;
DROP POLICY IF EXISTS "Lobby Member Access" ON coop_lobby_members;

-- Profiles
CREATE POLICY "Public Profiles" ON profiles FOR SELECT USING (true);
CREATE POLICY "Self Update Profile" ON profiles FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "Self Insert Profile" ON profiles FOR INSERT WITH CHECK (auth.uid() = id);

-- Subjects
CREATE POLICY "Public Read Subjects" ON subjects FOR SELECT USING (true);
CREATE POLICY "Teacher Manage Subjects" ON subjects FOR ALL USING (teacher_id = auth.uid());

-- Decks
CREATE POLICY "Owner Manage Decks" ON decks FOR ALL USING (user_id = auth.uid());
CREATE POLICY "Public Read Decks" ON decks FOR SELECT USING (true);

-- Cards
CREATE POLICY "Public Read Cards" ON cards FOR SELECT USING (true);
CREATE POLICY "Owner Manage Cards" ON cards FOR ALL USING (
    EXISTS (SELECT 1 FROM decks WHERE id = cards.deck_id AND user_id = auth.uid())
);

-- Subject Enrollments
CREATE POLICY "Student Enroll" ON subject_enrollments FOR INSERT WITH CHECK (student_id = auth.uid());
CREATE POLICY "View Enrollments" ON subject_enrollments FOR SELECT USING (
    student_id = auth.uid() OR 
    EXISTS (SELECT 1 FROM subjects WHERE id = subject_id AND teacher_id = auth.uid())
);
CREATE POLICY "Teacher Manage Enrollments" ON subject_enrollments FOR UPDATE USING (
    EXISTS (SELECT 1 FROM subjects WHERE id = subject_id AND teacher_id = auth.uid())
);
CREATE POLICY "Delete Enrollments" ON subject_enrollments FOR DELETE USING (
    student_id = auth.uid() OR 
    EXISTS (SELECT 1 FROM subjects WHERE id = subject_id AND teacher_id = auth.uid())
);

-- Subject Decks
CREATE POLICY "Read Subject Decks" ON subject_decks FOR SELECT USING (true);
CREATE POLICY "Manage Subject Decks" ON subject_decks FOR ALL USING (
    EXISTS (SELECT 1 FROM subjects WHERE id = subject_id AND teacher_id = auth.uid())
);

-- Study Sessions
CREATE POLICY "Users Manage Sessions" ON study_sessions FOR ALL USING (user_id = auth.uid());
CREATE POLICY "Teachers View Subject Sessions" ON study_sessions FOR SELECT USING (
    subject_id IS NOT NULL AND EXISTS (SELECT 1 FROM subjects WHERE id = subject_id AND teacher_id = auth.uid())
);

-- Notifications
CREATE POLICY "Users Manage Own Notifications" ON notifications FOR ALL USING (recipient_id = auth.uid());
CREATE POLICY "System Insert Notifications" ON notifications FOR INSERT WITH CHECK (true);

-- Friendships
CREATE POLICY "Friendship Access" ON friendships FOR ALL USING (auth.uid() = user1_id OR auth.uid() = user2_id OR auth.uid() = requester_id);

-- Co-op Lobbies
CREATE POLICY "Lobby Access" ON coop_lobbies FOR ALL USING (true);
CREATE POLICY "Lobby Member Access" ON coop_lobby_members FOR ALL USING (true);

-- 4. RECREATE FUNCTIONS
DROP FUNCTION IF EXISTS enroll_in_subject;
DROP FUNCTION IF EXISTS approve_enrollment_request;
DROP FUNCTION IF EXISTS unenroll_from_subject;
DROP FUNCTION IF EXISTS delete_subject;
DROP FUNCTION IF EXISTS delete_deck;
DROP FUNCTION IF EXISTS update_deck_with_cards;
DROP FUNCTION IF EXISTS get_subject_analytics;

-- Improved Enroll Function with Case-Insensitivity
CREATE OR REPLACE FUNCTION enroll_in_subject(subject_code_to_enroll text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_subject_id bigint;
  v_teacher_id uuid;
BEGIN
  -- Perform case-insensitive comparison
  SELECT id, teacher_id INTO v_subject_id, v_teacher_id 
  FROM subjects 
  WHERE UPPER(TRIM(subject_code)) = UPPER(TRIM(subject_code_to_enroll));

  IF v_subject_id IS NULL THEN RETURN json_build_object('success', false, 'message', 'Invalid code. Please check the code and try again.'); END IF;

  -- Insert Enrollment
  INSERT INTO subject_enrollments (subject_id, student_id, status) VALUES (v_subject_id, auth.uid(), 'pending') ON CONFLICT DO NOTHING;

  -- Failsafe Notification: If this block fails (e.g. recursion/RLS), catch it and continue so enrollment persists
  BEGIN
    INSERT INTO notifications (recipient_id, actor_id, type, related_entity_id, related_subject_id)
    VALUES (v_teacher_id, auth.uid(), 'enrollment_request'::text, (SELECT id FROM subject_enrollments WHERE subject_id = v_subject_id AND student_id = auth.uid()), v_subject_id);
  EXCEPTION WHEN OTHERS THEN
    -- Log warning but allow success
    RAISE WARNING 'Notification failed: %', SQLERRM;
  END;

  RETURN json_build_object('success', true, 'message', 'Request sent.');
END;
$$;

CREATE OR REPLACE FUNCTION approve_enrollment_request(enrollment_id bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_student_id uuid;
  v_subject_id bigint;
BEGIN
  UPDATE subject_enrollments SET status = 'approved' WHERE id = enrollment_id RETURNING student_id, subject_id INTO v_student_id, v_subject_id;
  IF v_student_id IS NOT NULL THEN
    BEGIN
      INSERT INTO notifications (recipient_id, actor_id, type, related_entity_id, related_subject_id)
      VALUES (v_student_id, auth.uid(), 'enrollment_approved'::text, enrollment_id, v_subject_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Approval Notification failed: %', SQLERRM;
    END;
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION unenroll_from_subject(subject_id_to_unenroll bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  DELETE FROM subject_enrollments WHERE subject_id = subject_id_to_unenroll AND student_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION delete_subject(subject_id_to_delete bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  DELETE FROM subjects WHERE id = subject_id_to_delete AND teacher_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION delete_deck(deck_id_to_delete bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM decks WHERE id = deck_id_to_delete AND user_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION update_deck_with_cards(p_deck_id bigint, p_title text, p_is_assessment boolean, p_cards jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    card_item jsonb;
BEGIN
    UPDATE decks SET title = p_title, is_assessment = p_is_assessment WHERE id = p_deck_id AND user_id = auth.uid();
    DELETE FROM cards WHERE deck_id = p_deck_id;
    FOR card_item IN SELECT * FROM jsonb_array_elements(p_cards)
    LOOP
        INSERT INTO cards (deck_id, question, answer, options, correctanswer)
        VALUES (
            p_deck_id,
            card_item->>'question',
            card_item->>'answer',
            (SELECT array_agg(x) FROM jsonb_array_elements_text(card_item->'options') t(x)),
            card_item->>'correctanswer'
        );
    END LOOP;
END;
$$;

-- FIX ANALYTICS FUNCTION WITH EXPLICIT TYPES
CREATE OR REPLACE FUNCTION get_subject_analytics(p_subject_id bigint) 
RETURNS TABLE (student_name text, deck_title text, score_percentage integer, completed_at timestamptz) 
LANGUAGE plpgsql 
SECURITY DEFINER 
AS $$
BEGIN
    RETURN QUERY 
    SELECT 
        p.full_name::text, 
        d.title::text, 
        COALESCE(ss.score_percentage, 0)::integer, 
        ss.completed_at::timestamptz
    FROM study_sessions ss 
    JOIN profiles p ON ss.user_id = p.id 
    JOIN decks d ON ss.deck_id = d.id 
    WHERE ss.subject_id = p_subject_id;
END;
$$;

CREATE OR REPLACE FUNCTION admin_delete_user(user_id_to_delete uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM auth.users WHERE id = user_id_to_delete;
END;
$$;

CREATE OR REPLACE FUNCTION admin_delete_subject(subject_id_to_delete bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM subjects WHERE id = subject_id_to_delete;
END;
$$;

CREATE OR REPLACE FUNCTION admin_search_students(search_term text) RETURNS TABLE (id uuid, full_name text, email text, course text, avatar_url text, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.email, p.course, p.avatar_url, p.created_at FROM profiles p WHERE p.role = 'Student' AND (search_term IS NULL OR p.full_name ILIKE '%'||search_term||'%' OR p.email ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION admin_search_teachers(search_term text) RETURNS TABLE (id uuid, full_name text, email text, course text, avatar_url text, created_at timestamptz, subject_count bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.email, p.course, p.avatar_url, p.created_at, (SELECT COUNT(*) FROM subjects s WHERE s.teacher_id = p.id) FROM profiles p WHERE p.role = 'Teacher' AND (search_term IS NULL OR p.full_name ILIKE '%'||search_term||'%' OR p.email ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION admin_search_subjects(search_term text) RETURNS TABLE (id bigint, title text, subject_code text, teacher_name text, student_count bigint, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT s.id, s.title, s.subject_code, p.full_name, (SELECT COUNT(*) FROM subject_enrollments se WHERE se.subject_id = s.id AND se.status = 'approved'), s.created_at FROM subjects s JOIN profiles p ON s.teacher_id = p.id WHERE (search_term IS NULL OR s.title ILIKE '%'||search_term||'%' OR s.subject_code ILIKE '%'||search_term||'%' OR p.full_name ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_stats() RETURNS TABLE (total_users bigint, student_users bigint, teacher_users bigint, total_subjects bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY SELECT (SELECT COUNT(*) FROM profiles), (SELECT COUNT(*) FROM profiles WHERE role = 'Student'), (SELECT COUNT(*) FROM profiles WHERE role = 'Teacher'), (SELECT COUNT(*) FROM subjects);
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_activity_trends() RETURNS TABLE (activity_date text, new_users bigint, study_sessions bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY WITH dates AS (SELECT generate_series(CURRENT_DATE - INTERVAL '6 days', CURRENT_DATE, '1 day'::interval)::date AS day)
  SELECT to_char(d.day, 'Mon DD'), (SELECT COUNT(*) FROM profiles p WHERE p.created_at::date = d.day), (SELECT COUNT(*) FROM study_sessions s WHERE s.completed_at::date = d.day) FROM dates d ORDER BY d.day ASC;
END;
$$;

CREATE OR REPLACE FUNCTION get_friends_and_requests() RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_friends json;
  v_requests json;
BEGIN
  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_friends
  FROM friendships f JOIN profiles p ON (CASE WHEN f.user1_id = v_user_id THEN f.user2_id ELSE f.user1_id END) = p.id
  WHERE (f.user1_id = v_user_id OR f.user2_id = v_user_id) AND f.status = 'accepted';

  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_requests
  FROM friendships f JOIN profiles p ON f.requester_id = p.id
  WHERE f.user2_id = v_user_id AND f.status = 'pending';

  RETURN json_build_object('friends', COALESCE(v_friends, '[]'::json), 'requests', COALESCE(v_requests, '[]'::json));
END;
$$;

CREATE OR REPLACE FUNCTION search_students(search_term text) RETURNS TABLE (id uuid, full_name text, avatar_url text, course text) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.avatar_url, p.course FROM profiles p WHERE p.role = 'Student' AND p.id != auth.uid() AND p.full_name ILIKE '%'||search_term||'%' LIMIT 20;
END;
$$;

