-- Improved Enroll Function with Case-Insensitivity (No Notifications)
CREATE OR REPLACE FUNCTION enroll_in_subject(subject_code_to_enroll text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_subject_id bigint;
  v_teacher_id uuid;
BEGIN
  -- Perform case-insensitive comparison
  SELECT id, teacher_id INTO v_subject_id, v_teacher_id 
  FROM subjects 
  WHERE UPPER(TRIM(subject_code)) = UPPER(TRIM(subject_code_to_enroll));

  IF v_subject_id IS NULL THEN RETURN json_build_object('success', false, 'message', 'Invalid code. Please check the code and try again.'); END IF;

  -- Insert Enrollment
  INSERT INTO subject_enrollments (subject_id, student_id, status) VALUES (v_subject_id, auth.uid(), 'pending') ON CONFLICT DO NOTHING;

  RETURN json_build_object('success', true, 'message', 'Request sent.');
END;
$$;

