  v_user_id uuid := auth.uid();
  v_friends json;
  v_requests json;
BEGIN
  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_friends
  FROM friendships f JOIN profiles p ON (CASE WHEN f.user1_id = v_user_id THEN f.user2_id ELSE f.user1_id END) = p.id
  WHERE (f.user1_id = v_user_id OR f.user2_id = v_user_id) AND f.status = 'accepted';

  SELECT json_agg(json_build_object('friendship_id', f.id, 'id', p.id, 'full_name', p.full_name, 'avatar_url', p.avatar_url, 'course', p.course)) INTO v_requests
  FROM friendships f JOIN profiles p ON f.requester_id = p.id
  WHERE f.user2_id = v_user_id AND f.status = 'pending';

  RETURN json_build_object('friends', COALESCE(v_friends, '[]'::json), 'requests', COALESCE(v_requests, '[]'::json));
END;
$$;

