interface CoopLobbyPageProps {
    user: User;
    lobby: CoopLobby;
    members: CoopLobbyMember[];
    onLeaveLobby: () => void;
    onGenerateNew: (lobby: CoopLobby) => void;
    onStartMatch: (lobby: CoopLobby) => void;
}

const CoopLobbyPage: React.FC<CoopLobbyPageProps> = ({ user, lobby, members, onLeaveLobby, onGenerateNew, onStartMatch }) => {
    const [selectedDeck, setSelectedDeck] = useState<Deck | null>(null);
    const [isDeckLoading, setIsDeckLoading] = useState(false);

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const [error, setError] = useState<string | null>(null);

    const isHost = user.id === lobby.host_id;

    useEffect(() => {
        const fetchDeckInfo = async () => {
            if (lobby.deck_id) {
                setIsDeckLoading(true);
                try {
                    const { data, error } = await supabase
                        .from('decks')
                        .select('*')
                        .eq('id', lobby.deck_id)
                        .single();
                    if (error) throw error;
                    setSelectedDeck(data);
                } catch (err) {
                    setError(`Failed to load selected deck: ${getErrorMessage(err)}`);
                    setSelectedDeck(null);
                } finally {
                    setIsDeckLoading(false);
                }
            } else {
                setSelectedDeck(null);
            }
        };

        fetchDeckInfo();
    }, [lobby.deck_id]);


    return (
        <div className="w-full h-full flex flex-col items-center justify-center p-4 sm:p-8 bg-primary-400/80 dark:bg-primary-700/80 rounded-2xl relative shadow-2xl animate-[fade-in_0.5s_ease-out]">
            <style>{`
