                }
            `}</style>

            <div className="absolute inset-0 bg-pattern opacity-50 dark:opacity-30 rounded-2xl"></div>

            <div className="absolute top-4 left-4 z-10">
                <button onClick={onLeaveLobby} className="flex items-center gap-2 text-white/80 hover:text-white font-bold bg-black/20 hover:bg-black/40 rounded-lg px-4 py-2 transition-all">
                    <DoorExitIcon className="w-6 h-6" />
                    <span>Exit Lobby</span>
                </button>
            </div>
             <div className="absolute top-4 right-4 z-10 text-white/80">
                <span className="font-bold">Lobby Code:</span> <span className="font-mono bg-black/20 p-1 rounded-md">{lobby.lobby_code}</span>
            </div>

            <div className="flex-grow flex flex-col items-center justify-center text-center text-white z-10 w-full">
                {isHost ? (
                    <div className="bg-black/20 p-4 sm:p-6 rounded-xl space-y-4">
                        {lobby.deck_id && selectedDeck ? (
                             <>
                                <h2 className="text-2xl sm:text-3xl font-bold">Game Ready!</h2>
                                <p className="text-white/80">Deck Selected: <span className="font-bold">{selectedDeck.title}</span></p>
                                <div className="flex flex-col sm:flex-row gap-4 pt-2 w-full max-w-md">
                                    <button
                                        onClick={() => onStartMatch(lobby)}
                                        className="flex-1 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-lg p-4 font-bold text-base hover:from-green-600 hover:to-green-700 transition-all shadow-lg transform hover:scale-105"
                                    >
                                        Start Game for Everyone
                                    </button>
                                </div>
                            </>
                        ) : isDeckLoading ? (
                            <LoadingView title="Loading Deck..." message="Please wait." />
                        ) : (
                            <>
                                <h2 className="text-2xl sm:text-3xl font-bold">Start the Game</h2>
                                <p className="text-white/80">Generate a new custom deck for this session.</p>
                                <div className="flex flex-col sm:flex-row gap-4 pt-2 w-full max-w-md">
                                    <button
                                        onClick={() => onGenerateNew(lobby)}
                                        className="flex-1 flex items-center justify-center gap-2 bg-gradient-to-r from-primary-400 to-primary-500 text-white rounded-lg p-4 font-bold text-base hover:from-primary-500 hover:to-primary-600 transition-all shadow-lg transform hover:scale-105 cursor-pointer"
                                    >
                                        <PlusCircleIcon className="w-7 h-7"/>
                                        Create New Deck
                                    </button>
                                </div>
                            </>
                        )}
                    </div>
                ) : (
                     <div className="bg-black/20 p-4 sm:p-6 rounded-xl">
                        {lobby.deck_id && selectedDeck ? (
                            <>
                                <h2 className="text-2xl sm:text-3xl font-bold">Game Ready!</h2>
                                <p className="mt-2 text-white/80">Deck: <span className="font-bold">{selectedDeck.title}</span></p>
