                                </div>
                            )}
                        </div>
                        <p className="font-bold mt-2 truncate text-sm sm:text-base">{member.user_id === user.id ? 'You' : member.profiles.full_name}</p>
                    </div>
                ))}
            </div>
        </div>
    );
};

