    subject_code text DEFAULT substring(md5(random()::text) from 1 for 6),
    created_at timestamptz DEFAULT now()
);
-- Ensure unique subject_code
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'subjects_subject_code_key') THEN
        ALTER TABLE public.subjects ADD CONSTRAINT subjects_subject_code_key UNIQUE (subject_code);
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.decks (
