  DELETE FROM subject_enrollments WHERE subject_id = subject_id_to_unenroll AND student_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION delete_subject(subject_id_to_delete bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  DELETE FROM subjects WHERE id = subject_id_to_delete AND teacher_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION delete_deck(deck_id_to_delete bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    DELETE FROM decks WHERE id = deck_id_to_delete AND user_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION update_deck_with_cards(p_deck_id bigint, p_title text, p_is_assessment boolean, p_cards jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    card_item jsonb;
BEGIN
    UPDATE decks SET title = p_title, is_assessment = p_is_assessment WHERE id = p_deck_id AND user_id = auth.uid();
    DELETE FROM cards WHERE deck_id = p_deck_id;
    FOR card_item IN SELECT * FROM jsonb_array_elements(p_cards)
    LOOP
        INSERT INTO cards (deck_id, question, answer, options, correctanswer)
        VALUES (
            p_deck_id,
            card_item->>'question',
            card_item->>'answer',
            (SELECT array_agg(x) FROM jsonb_array_elements_text(card_item->'options') t(x)),
            card_item->>'correctanswer'
        );
    END LOOP;
END;
$$;

-- FIX ANALYTICS FUNCTION WITH EXPLICIT TYPES
CREATE OR REPLACE FUNCTION get_subject_analytics(p_subject_id bigint) 
RETURNS TABLE (student_name text, deck_title text, score_percentage integer, completed_at timestamptz) 
LANGUAGE plpgsql 
SECURITY DEFINER 
AS $$
BEGIN
    RETURN QUERY 
    SELECT 
        p.full_name::text, 
        d.title::text, 
        COALESCE(ss.score_percentage, 0)::integer, 
        ss.completed_at::timestamptz
    FROM study_sessions ss 
    JOIN profiles p ON ss.user_id = p.id 
    JOIN decks d ON ss.deck_id = d.id 
    WHERE ss.subject_id = p_subject_id;
END;
$$;

