END;
$$;

CREATE OR REPLACE FUNCTION admin_search_students(search_term text) RETURNS TABLE (id uuid, full_name text, email text, course text, avatar_url text, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.email, p.course, p.avatar_url, p.created_at FROM profiles p WHERE p.role = 'Student' AND (search_term IS NULL OR p.full_name ILIKE '%'||search_term||'%' OR p.email ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION admin_search_teachers(search_term text) RETURNS TABLE (id uuid, full_name text, email text, course text, avatar_url text, created_at timestamptz, subject_count bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT p.id, p.full_name, p.email, p.course, p.avatar_url, p.created_at, (SELECT COUNT(*) FROM subjects s WHERE s.teacher_id = p.id) FROM profiles p WHERE p.role = 'Teacher' AND (search_term IS NULL OR p.full_name ILIKE '%'||search_term||'%' OR p.email ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION admin_search_subjects(search_term text) RETURNS TABLE (id bigint, title text, subject_code text, teacher_name text, student_count bigint, created_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY SELECT s.id, s.title, s.subject_code, p.full_name, (SELECT COUNT(*) FROM subject_enrollments se WHERE se.subject_id = s.id AND se.status = 'approved'), s.created_at FROM subjects s JOIN profiles p ON s.teacher_id = p.id WHERE (search_term IS NULL OR s.title ILIKE '%'||search_term||'%' OR s.subject_code ILIKE '%'||search_term||'%' OR p.full_name ILIKE '%'||search_term||'%');
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_stats() RETURNS TABLE (total_users bigint, student_users bigint, teacher_users bigint, total_subjects bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY SELECT (SELECT COUNT(*) FROM profiles), (SELECT COUNT(*) FROM profiles WHERE role = 'Student'), (SELECT COUNT(*) FROM profiles WHERE role = 'Teacher'), (SELECT COUNT(*) FROM subjects);
END;
$$;

CREATE OR REPLACE FUNCTION get_admin_activity_trends() RETURNS TABLE (activity_date text, new_users bigint, study_sessions bigint) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY WITH dates AS (SELECT generate_series(CURRENT_DATE - INTERVAL '6 days', CURRENT_DATE, '1 day'::interval)::date AS day)
  SELECT to_char(d.day, 'Mon DD'), (SELECT COUNT(*) FROM profiles p WHERE p.created_at::date = d.day), (SELECT COUNT(*) FROM study_sessions s WHERE s.completed_at::date = d.day) FROM dates d ORDER BY d.day ASC;
END;
$$;

COMMIT;
`;

export const getErrorMessage = (error: unknown): string => {
    // 1. Handle explicit strings first.
    if (typeof error === 'string') {
        // Fallback catch for the specific message reported by the user, forcing the fix UI.
        if (error.includes("Unable to save: A related record") || error.includes("User Profile) is missing")) {
             return 'DATABASE_RECURSION_ERROR:Profile Missing. Your account is missing a required profile record. Run the SQL fix below.';
        }
        return error;
    }

    let message = '';

    // 2. Handle objects with a string 'message' property (most common for Supabase/API errors).
    if (error && typeof error === 'object' && 'message' in error && typeof (error as { message: unknown }).message === 'string') {
        message = (error as { message: string }).message;
    }
    // 3. Handle standard JavaScript Error objects.
    else if (error instanceof Error) {
        message = error.message;
    }

    // Specific catch for the persisting foreign key error
    if (message.includes('fk_subject_code_exists') || message.includes('subject_codes')) {
        return 'DATABASE_RECURSION_ERROR:Obsolete database constraint detected. The system is trying to check a table that should not exist. Run the SQL fix below to remove the "fk_subject_code_exists" constraint.';
    }

    // Translate common technical errors
    if (message.includes('duplicate key value violates unique constraint')) {
        return 'An item with this name or code already exists. Please choose a different one.';
    }

    // Improve Foreign Key Violation and RLS Error Messaging to trigger SQL Fix
    if (message.includes('violates foreign key constraint') || message.includes('violates row-level security policy') || message.includes('violates check constraint')) {
        // "update or delete on table" specifically implies that the current item cannot be removed because other tables reference it.
        if (message.includes('update or delete on table') && !message.includes('profiles')) {
             // This logic is now likely handled by CASCADE, but kept for other edge cases
             return 'This item cannot be deleted because it is being used by other records (e.g., enrolled students or linked decks).';
        }
        // "insert or update on table" implies the item we are trying to save references a parent that doesn't exist or permissions are wrong.
        // Return a DATABASE_RECURSION_ERROR type string to trigger the SQL fix UI in the modal
        return 'DATABASE_RECURSION_ERROR:Database Sync Required. Your account is missing a required profile record or a database policy is blocking the action. Run the SQL fix below to repair it.';
    }

    if (message.includes('User not found')) {
        return 'No user was found with the provided credentials.';
    }
     if (message.includes('Invalid login credentials')) {
        return 'Invalid email or password. Please try again.';
    }
    if (message.includes('structure of query does not match function result type')) {
        return 'SCHEMA_CACHE_ERROR:The analytics function in the database has a data type mismatch. The app expected one format, but the database sent another. This requires a database update. Please ask your administrator to apply the latest SQL script for `get_subject_analytics`.';
    }
    if (message.includes('Could not choose the best candidate function')) {
        return 'SCHEMA_CACHE_ERROR:The database has conflicting function versions. Please run the updated SQL script in the Supabase editor to resolve this.';
    }
    if (message.includes('relation') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Missing Database Relation.");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Missing database relations (tables/views). Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('function') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Missing Database Function.");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Missing database functions. Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('column') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Schema mismatch (missing column).");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Database schema mismatch (missing column). Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('stack depth limit exceeded') || message.includes('infinite recursion')) {
        console.error("CRITICAL DATABASE ERROR: Infinite recursion in RLS policies detected.");
        console.log("SQL FIX:\n", FIX_RECURSION_SQL); // Log to console for easy access
        return 'DATABASE_RECURSION_ERROR: Infinite recursion detected in database policies. Please run the fixed SQL script in Supabase to resolve the RLS loop.';
    }
    if (message.includes('cannot alter type of a column used by a view or rule')) {
        console.error("CRITICAL DATABASE ERROR: Dependent views blocking schema update.");
        console.log("SQL FIX:\n", FIX_RECURSION_SQL);
        return 'DATABASE_RECURSION_ERROR: Dependent views blocking update. Run the fixed SQL script to drop views and update schema.';
    }

    // Supabase paused / Network issues
    if (message.includes('Failed to fetch') || message.includes('NetworkError') || message.includes('503')) {
        return 'Unable to connect to the server. The database might be paused due to inactivity. Please check the Supabase dashboard to restore the project.';
    }

    if (message) {
        return message;
    }

    // 4. As a fallback, try to stringify the entire error object.
    try {
        const str = JSON.stringify(error, null, 2); // Pretty-print for better debugging
        if (str !== '{}') {
            return str;
        }
    } catch {
        // Fall through to the final, safest fallback.
    }

    // 5. The ultimate fallback.
    try {
        return `[Unstructured Error]: ${String(error)}`;
    } catch {
        return 'An unknown and un-stringifiable error occurred.';
    }
};

